// Authored teaching content; all examples and diagnostic output are illustrative.
const step=(from,to,title,relation,text,packet)=>({from,to,title,relation,kind:{containment:'Containment · not a network hop',ownership:'Ownership · not application traffic',network:'Network exchange',configuration:'Configuration reference · logical',storage:'Storage relationship · logical',control:'Control / reconciliation'}[relation],text,packet});
export const k8sLessons=[
 {id:'inside',title:'1. Where does the app run?',focus:'worker-a',nodes:['worker-a','pod-a','app-a'],goal:'Understand a node, a Pod and a container before adding anything else.',why:'A node runs the Pod. The Pod groups containers. The application process runs inside a container.',steps:[step('worker-a','pod-a','The node hosts a Pod','containment','The worker is a machine. This Pod is scheduled onto it. The arrow means “hosts”, not that HTTP flows from the machine to another server.','Node → hosted Pod'),step('pod-a','app-a','The Pod contains the app container','containment','The Pod supplies shared networking and declared volumes to its containers. This one app container runs our example process.','Pod → application process')],question:'Where does the application process run?',options:['Inside the application container','Inside the Service object','Inside the scheduler'],correct:0,answer:'The container runs the application process. Its Pod supplies shared networking; the node supplies the runtime and kernel.'},
 {id:'ownership',title:'2. Who keeps the Pods running?',focus:'cluster',nodes:['deployment','replicaset','worker-a','worker-b','pod-a','pod-b','app-a','app-b'],goal:'Follow desired replicas and ownership without mixing them with HTTP traffic.',why:'Controllers reconcile desired state. Replacing a Pod creates a new Pod; it does not bring back the old process memory.',steps:[step('deployment','replicaset','Declare the desired application replicas','ownership','The Deployment controller manages ReplicaSets through API operations. This is an ownership relationship, not a direct connection between running application servers.','Deployment → managed ReplicaSet'),step('replicaset','pod-a','Maintain the desired Pod count','ownership','The ReplicaSet controller creates missing Pod resources through the API. The scheduler places new Pods and the kubelet starts their containers.','ReplicaSet → owned Pod A'),step('replicaset','pod-b','Keep a second instance available','ownership','This example spreads two replicas over two workers. Actual placement requires eligible capacity and appropriate scheduling rules.','ReplicaSet → owned Pod B')],question:'If an owned Pod is deleted, what normally maintains the desired count?',options:['The container registry','ReplicaSet reconciliation','A Service forwards a replacement Pod'],correct:1,answer:'The ReplicaSet controller reconciles the desired count. A replacement is a new Pod that must be scheduled and started.'},
 {id:'request',title:'3. How does a request reach the app?',focus:'cluster',nodes:['users','ingress','service','worker-a','pod-a','app-a'],goal:'Trace one request and its response; keep the control plane out of HTTP forwarding.',why:'Ingress handles HTTP routing, while Service configuration identifies eligible backends. A Service is not another application server.',steps:[step('users','ingress','Send a request to the configured entry','network','This simplified boundary view starts after public DNS and any external load balancer. The client reaches the configured Ingress controller.','HTTPS :443 example → Ingress controller'),step('ingress','service','Choose the application backend','configuration','The controller uses a Service backend reference. Some implementations connect directly to endpoint addresses; Service is not necessarily an extra proxy hop.','Host/path → Service backend / ready endpoints'),step('service','app-a','Deliver to an eligible application listener','network','The Service dataplane routes to a ready Pod endpoint, then the Pod network delivers to the real app listener. This arrow abbreviates those network boundaries.','Service :80 → Pod/app :8080 example'),step('app-a','ingress','Return the application response','network','The response returns through the established network/controller path. The API server and scheduler do not carry this HTTP response.','HTTP 200 + body → upstream connection'),step('ingress','users','Return the result to the client','network','This completes the simplified request boundary. External load balancer and DNS details remain in the existing full request journey.','HTTPS response → client')],question:'Does ordinary application HTTP traffic pass through the Kubernetes API server?',options:['Yes, every request','No, the API manages cluster state','Only when there are two replicas'],correct:1,answer:'The API is part of the control plane. The application request uses the configured Ingress and Service/Pod dataplane.'},
 {id:'config',title:'4. Where does configuration come from?',focus:'cluster',nodes:['configmap','secret','worker-a','pod-a','app-a','env','mounts','security-context'],goal:'Separate ordinary configuration, sensitive values and how the app consumes them.',why:'Creating a ConfigMap or Secret is not enough: the workload must reference it, and the process must use the provided value.',steps:[step('configmap','env','Reference ordinary configuration','configuration','The Pod specification can reference a ConfigMap through environment entries or volumes. This is a configuration dependency, not a ConfigMap network server.','ConfigMap reference → Pod environment'),step('secret','env','Reference sensitive configuration','configuration','The workload references the intended Secret and needs appropriate access controls. Base64 encoding is not encryption. No real values are shown.','Secret reference → required environment value'),step('env','app-a','Read configuration at process startup','configuration','Our example app requires DATABASE_URL. Updating a Secret does not automatically refresh a value already copied into a running process environment.','DATABASE_URL reference → app process')],question:'A required Secret exists, but the app is missing DATABASE_URL. What should you check?',options:['Whether the workload references the required key','Whether the scheduler can answer HTTP','Whether all probes can be removed'],correct:0,answer:'Check the workload reference, key and application expectations. Existence of the Secret alone does not inject an environment variable.'},
 {id:'storage',title:'5. What survives a Pod replacement?',focus:'cluster',nodes:['worker-a','pod-a','app-a','volume-a','mounts','pvc','csi'],goal:'Distinguish a mounted volume, a claim and storage provisioning.',why:'A container’s writable layer and a Pod-lifetime emptyDir are not substitutes for deliberately provisioned persistent storage.',steps:[step('pvc','csi','Request supported persistent storage','storage','A PVC requests storage. Depending on the class and driver, provisioning and PV binding provide a usable volume. PV and the storage backend are abbreviated in this small lesson.','PVC → storage class / provisioner / PV binding'),step('pvc','mounts','Reference the claim from the Pod','storage','For a PVC-backed workload, the Pod references the bound claim and the driver/kubelet make the supported mount available. The example Pod’s displayed shared volume is not automatically this PVC.','Bound claim → declared volume + mount path'),step('mounts','app-a','Access mounted files','storage','The application uses the mount path. Persistence, access modes, permissions and reclaim policy depend on the actual storage design.','Configured mount path → application file access')],question:'Does every volume automatically survive Pod deletion?',options:['Yes, including every emptyDir','No, persistence depends on the volume type and lifecycle','Only if the Service has two ports'],correct:1,answer:'emptyDir lives with its Pod. Persistent storage needs a suitable volume source, lifecycle and recovery design.'},
 {id:'health',title:'6. Is running the same as ready?',focus:'worker-a',nodes:['worker-a','kubelet-a','pod-a','app-a','startup-probe','readiness','liveness','requests','limits','events'],goal:'Separate startup, readiness, liveness and resource-related symptoms.',why:'A running container can still be unable to serve users. A readiness failure and a liveness failure have different consequences.',steps:[step('kubelet-a','startup-probe','Allow the application to start','control','When configured, a startup probe gates the normal liveness and readiness checks until startup succeeds.','Startup result → startup decision'),step('kubelet-a','readiness','Check whether this instance can serve','control','Readiness affects whether the Pod is an eligible Service endpoint. A failed readiness probe does not itself restart the container.','Readiness result → endpoint eligibility'),step('kubelet-a','liveness','Check whether the container needs restarting','control','A failing configured liveness probe can cause the kubelet to restart the affected container according to its policy. Poor probes can create outages.','Liveness failure threshold → container restart'),step('limits','events','Investigate a resource-related failure','configuration','Memory limits can lead to OOM termination. CPU limits can cause throttling. Read the evidence rather than assuming every restart has one cause.','Limit + observed event → investigation evidence')],question:'What does a failed readiness probe normally change?',options:['It always deletes the node','The Pod’s eligibility to receive Service traffic','It always restarts the container'],correct:1,answer:'Readiness controls serving eligibility. Liveness is the separate probe associated with restarting a container.'},
 {id:'control',title:'7. How does a new Pod start?',focus:'cluster',nodes:['control-plane','api','etcd','controllers','deployment','replicaset','scheduler','worker-a','kubelet-a','runtime-a','pod-a','app-a'],goal:'Connect control-plane decisions with node-side execution.',why:'The scheduler chooses placement; the kubelet and runtime execute the assigned Pod. These are different responsibilities.',steps:[step('api','etcd','Store admitted cluster state','control','After authentication, authorization and admission, the API server stores supported API state in etcd. Applications do not use etcd as their product database.','Admitted API resource → persisted state'),step('api','controllers','Observe desired state','control','Controllers watch the API and reconcile differences. Deployment/ReplicaSet reconciliation creates the desired Pod resources through the API.','Resource watch → reconciliation'),step('api','scheduler','Observe an unscheduled Pod','control','The scheduler observes Pods without an assigned node, evaluates eligible capacity and constraints, and records placement through the API.','Unscheduled Pod → scheduling decision'),step('scheduler','kubelet-a','Observe the assigned Pod','control','This arrow abbreviates a binding recorded through the API and the kubelet observing that assignment; the scheduler does not directly execute the process.','API binding → kubelet’s assigned Pod'),step('kubelet-a','runtime-a','Ask the runtime to prepare containers','control','Kubelet uses the configured CRI runtime. The runtime retrieves images using configured identity; those image transfers are omitted here.','CRI request → container runtime'),step('runtime-a','app-a','Start the application process','control','With prerequisites, image and configuration available, the runtime starts the process. Readiness still needs to be established.','Container specification → running process')],question:'Which component chooses a node for an unscheduled Pod?',options:['The scheduler','The container registry','The Ingress controller'],correct:0,answer:'The scheduler chooses eligible placement. Kubelet and runtime on the assigned worker handle execution.'}
];
export function installK8sFlows(flows){for(const l of k8sLessons)flows['learn-k8s-'+l.id]={label:l.title,color:0x7ddfea,steps:l.steps};}
export function lessonVisibleIds(nodes,ids){const allowed=new Set(ids);for(const id of ids){let n=nodes.find(n=>n.id===id);if(!n)throw Error('Unknown lesson node '+id);while(n?.parent){allowed.add(n.parent);n=nodes.find(p=>p.id===n.parent);}}return allowed;}
export const relationColors={containment:0x9ba9bc,ownership:0xd6b0ff,configuration:0xffcd81,storage:0x8fdfaa,network:0x6be5ff,control:0xffa7b3};
export const k8sExamples={
 'app-a':{yaml:'apiVersion: v1\nkind: Pod\nmetadata:\n  name: web\n  labels: {app: web}\nspec:\n  containers:\n    - name: app\n      image: your-registry.example/learning-app:lab\n      ports:\n        - containerPort: 8080',status:'Example only: Pod web · container app · state Running. Running is not proof of readiness. This standalone manifest illustrates nesting, not a production deployment.',logs:'Example log: app started; listening on 0.0.0.0:8080. The image name in this manifest is a placeholder; substitute your lab image and its required configuration.'},
 service:{yaml:'apiVersion: v1\nkind: Service\nmetadata:\n  name: web\nspec:\n  selector: {app: web}\n  ports:\n    - port: 80\n      targetPort: 8080',status:'Example only: selector app=web matches the illustrative Pod above. EndpointSlices must contain eligible endpoints.',logs:'Services do not run an application process and do not have container logs. Inspect selectors, EndpointSlices and the real dataplane.'},
 deployment:{yaml:'apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: web\nspec:\n  replicas: 2\n  selector:\n    matchLabels: {app: web}\n  template:\n    metadata:\n      labels: {app: web}\n    spec:\n      containers:\n        - name: app\n          image: your-registry.example/learning-app:lab\n          ports:\n            - containerPort: 8080',status:'Example only: desired replicas = 2. Check updated, ready and available replica counts separately.',logs:'Deployments are API objects, not container processes. Select an owned Pod/container to inspect application logs.'},
 secret:{yaml:'apiVersion: v1\nkind: Secret\nmetadata:\n  name: app-config\ntype: Opaque\nstringData:\n  DATABASE_URL: REPLACE_IN_YOUR_DISPOSABLE_LAB',status:'Example only; placeholder value. A Secret must be referenced by the intended workload/key. Apply appropriate encryption and access controls.',logs:'Secrets do not have application logs. Never print real secret values into a learning report.'},
 configmap:{yaml:'apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: web-settings\ndata:\n  LOG_LEVEL: info',status:'Example only: ordinary non-sensitive settings. The workload still needs an explicit reference.',logs:'ConfigMaps are stored API objects, not running log-producing containers.'}
};

